import { Howl } from 'howler'
import { SoundEffects } from './types'

let soundsInstance: SoundEffects | null = null
let audioCtx: AudioContext | null = null

const getAudioContext = (): AudioContext | null => {
    if (typeof window === 'undefined') return null
    if (!audioCtx) {
        const AudioCtxClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
        if (AudioCtxClass) {
            audioCtx = new AudioCtxClass()
        }
    }
    if (audioCtx && audioCtx.state === 'suspended') {
        audioCtx.resume().catch(() => {})
    }
    return audioCtx
}

// GTA UI Click Synthesizer
export const playUiClick = (freq = 900, type: OscillatorType = 'sine') => {
    try {
        const ctx = getAudioContext()
        if (!ctx) return
        const osc = ctx.createOscillator()
        const gain = ctx.createGain()
        osc.type = type
        osc.frequency.setValueAtTime(freq, ctx.currentTime)
        osc.frequency.exponentialRampToValueAtTime(freq * 0.4, ctx.currentTime + 0.06)

        gain.gain.setValueAtTime(0.12, ctx.currentTime)
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.06)

        osc.connect(gain)
        gain.connect(ctx.destination)

        osc.start()
        osc.stop(ctx.currentTime + 0.06)
    } catch (_) {}
}

// GTA Wanted Star Impact / Thump Sound
export const playStarChime = (starNum: number) => {
    try {
        const ctx = getAudioContext()
        if (!ctx) return
        const now = ctx.currentTime

        // Bass thump
        const subOsc = ctx.createOscillator()
        const subGain = ctx.createGain()
        subOsc.type = 'triangle'
        subOsc.frequency.setValueAtTime(120 + starNum * 20, now)
        subOsc.frequency.exponentialRampToValueAtTime(35, now + 0.28)

        subGain.gain.setValueAtTime(0.3, now)
        subGain.gain.exponentialRampToValueAtTime(0.001, now + 0.28)

        subOsc.connect(subGain)
        subGain.connect(ctx.destination)

        subOsc.start(now)
        subOsc.stop(now + 0.28)

        // Metallic star chime
        const chimeOsc = ctx.createOscillator()
        const chimeGain = ctx.createGain()
        chimeOsc.type = 'sine'
        const baseFreq = 440 + starNum * 110
        chimeOsc.frequency.setValueAtTime(baseFreq, now)
        chimeOsc.frequency.exponentialRampToValueAtTime(baseFreq * 1.5, now + 0.18)

        chimeGain.gain.setValueAtTime(0.18, now)
        chimeGain.gain.exponentialRampToValueAtTime(0.001, now + 0.2)

        chimeOsc.connect(chimeGain)
        chimeGain.connect(ctx.destination)

        chimeOsc.start(now)
        chimeOsc.stop(now + 0.2)
    } catch (_) {}
}

// Subtle Hover tick
export const playHover = () => {
    try {
        const ctx = getAudioContext()
        if (!ctx) return
        const osc = ctx.createOscillator()
        const gain = ctx.createGain()
        osc.type = 'sine'
        osc.frequency.setValueAtTime(1400, ctx.currentTime)

        gain.gain.setValueAtTime(0.04, ctx.currentTime)
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.02)

        osc.connect(gain)
        gain.connect(ctx.destination)

        osc.start()
        osc.stop(ctx.currentTime + 0.02)
    } catch (_) {}
}

export const getSounds = (): SoundEffects => {
    if (typeof window === 'undefined') {
        return {}
    }

    if (!soundsInstance) {
        soundsInstance = {
            siren: new Howl({
                src: ['/sounds/siren_loop.mp3'],
                volume: 0.5,
                preload: true,
            }),
            ambience: new Howl({
                src: ['/sounds/loading_ambience.mp3'],
                loop: true,
                volume: 0.45,
                preload: true,
            }),
            passed: new Howl({
                src: ['/sounds/mission_passed.mp3'],
                volume: 1.0,
                preload: true,
            }),
            failed: new Howl({
                src: ['/sounds/mission_failed.mp3'],
                volume: 1.0,
                preload: true,
            }),
        }
    }

    return soundsInstance
}
