'use client'
import React, { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'
import { Howler } from 'howler'
import { BasePhaseProps } from '@/lib/types'
import { playStarChime } from '@/lib/sounds'

interface StarIconProps {
    className?: string
    style?: React.CSSProperties
    filled?: boolean
    flashing?: boolean
}

function StarIcon({ className, style, filled = false, flashing = false }: StarIconProps) {
    return (
        <svg
            className={`${className || ''} wanted-star-svg ${flashing && filled ? 'gta-wanted-flash' : ''}`}
            style={style}
            viewBox="0 0 72 72"
            width="56"
            height="56"
        >
            <polygon
                points="36,4 44,28 70,28 49,44 57,68 36,52 15,68 23,44 2,28 28,28"
                fill={filled ? '#ffffff' : 'rgba(20, 20, 20, 0.75)'}
                stroke={filled ? '#ffffff' : 'rgba(255, 255, 255, 0.45)'}
                strokeWidth="2.5"
                style={{
                    filter: filled
                        ? 'drop-shadow(0 0 12px rgba(255, 255, 255, 0.95)) drop-shadow(0 0 24px rgba(255, 255, 255, 0.7))'
                        : 'none',
                }}
            />
        </svg>
    )
}

export default function WantedStars({ onComplete, sounds }: BasePhaseProps) {
    const containerRef = useRef<HTMLDivElement | null>(null)
    const redRef = useRef<HTMLDivElement | null>(null)
    const blueRef = useRef<HTMLDivElement | null>(null)
    const sweepRef = useRef<HTMLDivElement | null>(null)
    const starRefs = useRef<(HTMLDivElement | null)[]>([])
    const flashRef = useRef<HTMLDivElement | null>(null)
    const badgeRef = useRef<HTMLDivElement | null>(null)

    const [filledCount, setFilledCount] = useState<number>(0)
    const [isMaxWanted, setIsMaxWanted] = useState<boolean>(false)

    useEffect(() => {
        const siren = sounds?.siren

        // Start siren audio
        const startAudio = async () => {
            try {
                if (Howler && Howler.ctx && Howler.ctx.state !== 'running') {
                    await Howler.ctx.resume()
                }
                if (siren) {
                    siren.stop()
                    siren.volume(0.55)
                    siren.play()
                }
            } catch (err) {
                console.log('Audio notice:', err)
            }
        }
        startAudio()

        // Sweeping helicopter spotlight
        if (sweepRef.current) {
            gsap.to(sweepRef.current, {
                x: '120%',
                duration: 2.2,
                repeat: -1,
                ease: 'power1.inOut',
                yoyo: true,
            })
        }

        // Alternating Police Strobes
        const strobeTl = gsap.timeline({ repeat: -1 })
        if (redRef.current) {
            strobeTl
                .to(redRef.current, { opacity: 0.9, duration: 0.06 })
                .to(redRef.current, { opacity: 0.1, duration: 0.05 })
                .to(redRef.current, { opacity: 0.95, duration: 0.08 })
                .to(redRef.current, { opacity: 0, duration: 0.12 })
        }
        if (blueRef.current) {
            strobeTl
                .to(blueRef.current, { opacity: 0.9, duration: 0.06 }, '-=0.08')
                .to(blueRef.current, { opacity: 0.1, duration: 0.05 })
                .to(blueRef.current, { opacity: 0.95, duration: 0.08 })
                .to(blueRef.current, { opacity: 0, duration: 0.14 })
        }

        // Pop in animation for star
        const animateStarFill = (index: number) => {
            setFilledCount(index + 1)
            playStarChime(index + 1)

            const starEl = starRefs.current[index]
            if (starEl) {
                gsap.fromTo(
                    starEl,
                    { scale: 1.85, filter: 'brightness(2.5)' },
                    { scale: 1, filter: 'brightness(1)', duration: 0.45, ease: 'back.out(2.2)' }
                )
            }

            // Subtle screen bump
            if (containerRef.current) {
                gsap.fromTo(
                    containerRef.current,
                    { y: -4 },
                    { y: 0, duration: 0.15, ease: 'power2.out' }
                )
            }
        }

        // Master Timeline: 1-to-5 star progressive increase
        const masterTl = gsap.timeline({
            onComplete: () => {
                onComplete()
            },
        })

        // Star 1 at 0.5s
        masterTl.to({}, { duration: 0.1, onStart: () => animateStarFill(0) }, 0.5)

        // Star 2 at 1.7s
        masterTl.to({}, { duration: 0.1, onStart: () => animateStarFill(1) }, 1.7)

        // Star 3 at 2.9s
        masterTl.to({}, { duration: 0.1, onStart: () => animateStarFill(2) }, 2.9)

        // Star 4 at 4.1s
        masterTl.to({}, { duration: 0.1, onStart: () => animateStarFill(3) }, 4.1)

        // Star 5 at 5.3s (Max Wanted Climax!)
        masterTl.to(
            {},
            {
                duration: 0.1,
                onStart: () => {
                    animateStarFill(4)
                    setIsMaxWanted(true)

                    if (flashRef.current) {
                        gsap.fromTo(
                            flashRef.current,
                            { opacity: 0, scale: 0.4 },
                            {
                                opacity: 1,
                                scale: 6,
                                duration: 0.3,
                                ease: 'power2.out',
                                yoyo: true,
                                repeat: 1,
                            }
                        )
                    }

                    if (containerRef.current) {
                        gsap.fromTo(
                            containerRef.current,
                            { x: -12, y: -8 },
                            {
                                x: 12,
                                y: 8,
                                duration: 0.04,
                                repeat: 12,
                                yoyo: true,
                                ease: 'power2.inOut',
                                onComplete: () => {
                                    if (containerRef.current) {
                                        gsap.set(containerRef.current, { x: 0, y: 0 })
                                    }
                                },
                            }
                        )
                    }
                },
            },
            5.3
        )

        // Hold at max wanted until 7.8s then complete
        masterTl.to({}, { duration: 2.5 }, 5.3)

        // Key handler to skip
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.code === 'Space' || e.code === 'Enter') {
                onComplete()
            }
        }
        window.addEventListener('keydown', handleKeyDown)

        return () => {
            masterTl.kill()
            strobeTl.kill()
            window.removeEventListener('keydown', handleKeyDown)
            if (sweepRef.current) gsap.killTweensOf(sweepRef.current)
            if (containerRef.current) gsap.killTweensOf(containerRef.current)
            if (flashRef.current) gsap.killTweensOf(flashRef.current)
        }
    }, [onComplete, sounds])

    return (
        <div
            ref={containerRef}
            onClick={onComplete}
            style={{
                position: 'fixed',
                inset: 0,
                background: '#000',
                zIndex: 95,
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                userSelect: 'none',
                cursor: 'pointer',
            }}
        >
            <div className="noise-overlay" />
            <div className="crt-scanlines" />

            {/* Red Police Strobe */}
            <div
                ref={redRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background:
                        'radial-gradient(ellipse at 15% 50%, rgba(255, 0, 0, 0.7) 0%, rgba(200, 0, 0, 0.25) 45%, transparent 70%)',
                    opacity: 0,
                    mixBlendMode: 'screen',
                }}
            />

            {/* Blue Police Strobe */}
            <div
                ref={blueRef}
                style={{
                    position: 'absolute',
                    inset: 0,
                    background:
                        'radial-gradient(ellipse at 85% 50%, rgba(0, 102, 255, 0.7) 0%, rgba(0, 70, 220, 0.25) 45%, transparent 70%)',
                    opacity: 0,
                    mixBlendMode: 'screen',
                }}
            />

            {/* Searchlight Beam */}
            <div
                ref={sweepRef}
                style={{
                    position: 'absolute',
                    top: '-20%',
                    left: '-30%',
                    width: '60%',
                    height: '140%',
                    background:
                        'radial-gradient(ellipse at center, rgba(255, 255, 255, 0.15) 0%, transparent 60%)',
                    transform: 'rotate(-25deg)',
                    pointerEvents: 'none',
                    mixBlendMode: 'screen',
                }}
            />

            <div className="heavy-vignette" />

            {/* Screen Flash on Max Wanted */}
            <div
                ref={flashRef}
                style={{
                    position: 'absolute',
                    width: '320px',
                    height: '320px',
                    background: 'radial-gradient(circle, #ffffff 0%, rgba(255, 255, 255, 0.85) 30%, transparent 70%)',
                    opacity: 0,
                    filter: 'blur(20px)',
                    pointerEvents: 'none',
                    zIndex: 115,
                }}
            />

            {/* Top Police Dispatch HUD Tag */}
            <div
                ref={badgeRef}
                style={{
                    position: 'absolute',
                    top: '12%',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    gap: '4px',
                    zIndex: 110,
                }}
            >
                <div
                    style={{
                        fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                        fontSize: 'clamp(0.85rem, 1.8vw, 1.15rem)',
                        letterSpacing: '0.35em',
                        textTransform: 'uppercase',
                        color: isMaxWanted ? '#ff3333' : 'rgba(255, 255, 255, 0.7)',
                        textShadow: isMaxWanted ? '0 0 12px rgba(255, 50, 50, 0.9)' : 'none',
                        transition: 'color 0.3s ease',
                    }}
                >
                    {isMaxWanted ? '★ MAXIMUM WANTED LEVEL // LSPD DISPATCH' : 'SAN ANDREAS POLICE DEPARTMENT // DISPATCH'}
                </div>
                <div
                    style={{
                        fontFamily: 'ChaletLondon1960, "Bebas Neue", Montserrat, sans-serif',
                        fontSize: 'clamp(1.4rem, 3.2vw, 2.2rem)',
                        letterSpacing: '0.15em',
                        textTransform: 'uppercase',
                        color: '#ffffff',
                    }}
                >
                    WANTED LEVEL
                </div>
            </div>

            {/* 5 WANTED STARS IN ROW */}
            <div
                style={{
                    display: 'flex',
                    gap: '20px',
                    alignItems: 'center',
                    justifyContent: 'center',
                    zIndex: 110,
                    padding: '20px',
                }}
            >
                {[0, 1, 2, 3, 4].map((i) => {
                    const isFilled = i < filledCount
                    return (
                        <div
                            key={i}
                            ref={(el) => {
                                starRefs.current[i] = el
                            }}
                            style={{
                                display: 'inline-flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                            }}
                        >
                            <StarIcon
                                filled={isFilled}
                                flashing={isMaxWanted}
                            />
                        </div>
                    )
                })}
            </div>

            {/* Bottom GTA Skip Prompt */}
            <div
                style={{
                    position: 'absolute',
                    bottom: '10%',
                    fontFamily: 'ChaletComprime1960, "Barlow Condensed", sans-serif',
                    fontSize: '0.85rem',
                    letterSpacing: '0.25em',
                    color: 'rgba(255, 255, 255, 0.45)',
                    textTransform: 'uppercase',
                    zIndex: 110,
                }}
            >
                [ CLICK OR PRESS SPACE TO SKIP ]
            </div>
        </div>
    )
}
